import { type LeaseAllocateOptions } from 'agent-device';
/** One lease allocation from the daemon in `stateDir`, run in its own process so the daemon gets that process's environment. */
export interface DriverRequest {
    stateDir: string;
    allocate: LeaseAllocateOptions;
}
export interface DriverGrant {
    leaseId: string;
    tenantId: string;
    runId: string;
    retainOnClose: boolean;
}
